import React, { useState } from "react";
import { useNavigate, Link } from "react-router-dom";
import "../hojas-de-estilo/NavBar.css";
import logo from "../imagenes/logo.jpg";

export default function NavBar() {
  const [isOpen, setIsOpen] = useState(false);
  const navigate = useNavigate();

  const toggleMenu = () => setIsOpen(!isOpen);

  // --- Función para moverse a secciones del Home ---
  const goToSection = (id) => {
    setIsOpen(false); // cierra el menú si está abierto
    navigate("/"); // vuelve al home (ruta raíz del HashRouter)
    // espera un instante y luego hace scroll suave
    setTimeout(() => {
      const section = document.getElementById(id);
      if (section) {
        section.scrollIntoView({ behavior: "smooth", block: "start" });
      } else {
        // intenta varias veces si el elemento aún no existe
        let tries = 0;
        const interval = setInterval(() => {
          tries++;
          const node = document.getElementById(id);
          if (node) {
            node.scrollIntoView({ behavior: "smooth", block: "start" });
            clearInterval(interval);
          } else if (tries > 40) {
            clearInterval(interval);
          }
        }, 50);
      }
    }, 100);
  };

  return (
    <nav className="navbar navbar-expand-lg navbar-dark fixed-top">
      <div className="container-fluid">
        {/* Logo */}
        <Link className="navbar-brand" to="/" onClick={() => setIsOpen(false)}>
          <div className="img-contenedor">
            <img src={logo} alt="logo" />
          </div>
        </Link>

        {/* Botón toggle para móvil */}
        <button
          className="navbar-toggler"
          type="button"
          onClick={toggleMenu}
        >
          <span className="navbar-toggler-icon"></span>
        </button>

        {/* Menú */}
        <div className={`collapse navbar-collapse ${isOpen ? "show" : ""}`}>
          <ul className="navbar-nav ms-auto mb-2 mb-lg-0">
            <li className="nav-item">
              <button className="nav-link btn" onClick={() => goToSection("home")}>
                Home
              </button>
            </li>
            <li className="nav-item">
              <button className="nav-link btn" onClick={() => goToSection("servicio")}>
                Servicios
              </button>
            </li>
            <li className="nav-item">
              <button className="nav-link btn" onClick={() => goToSection("proyectos")}>
                Proyectos
              </button>
            </li>
            <li className="nav-item">
              <button className="nav-link btn" onClick={() => goToSection("testimonios")}>
                Testimonios
              </button>
            </li>
            <li className="nav-item">
              <Link
                className="nav-link fw-bold"
                to="/sacar-turno"
                onClick={() => setIsOpen(false)}
              >
                Turnos
              </Link>
            </li>
          </ul>
        </div>
      </div>
    </nav>
  );
}


